import React, { useState } from 'react';
import {
  TextInput,
  Text,
  StyleSheet,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  TouchableOpacity,
  View,
} from 'react-native';
import { auth } from '../services/firebaseConfig';
import {
  createUserWithEmailAndPassword,
  sendEmailVerification,
} from 'firebase/auth';
import { getFirestore, setDoc, doc } from 'firebase/firestore';
import Toast from 'react-native-toast-message';

const db = getFirestore();

function NeumorphicField({ children, style }: any) {
  return (
    <View style={[estilos.neumorphicOuter, style]}>
      <View style={estilos.neumorphicInner}>{children}</View>
    </View>
  );
}

function NeumorphicButton({ children, onPress, style }: any) {
  return (
    <TouchableOpacity onPress={onPress} activeOpacity={0.85} style={{ width: '100%' }}>
      <View style={[estilos.neumorphicOuter, style]}>
        <View style={estilos.neumorphicInner}>{children}</View>
      </View>
    </TouchableOpacity>
  );
}

export default function TelaCadastro({ navigation }: any): JSX.Element {
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');

  async function registrarUsuario() {
    if (!email || !senha) {
      Toast.show({
        type: 'error',
        text1: 'Erro',
        text2: 'Preencha email e senha',
      });
      return;
    }

    Toast.show({
      type: 'info',
      text1: 'Atenção',
      text2: 'Verifique seu e-mail e confirme antes de fazer login.',
      visibilityTime: 3500,
    });

    try {
      const credencial = await createUserWithEmailAndPassword(auth, email, senha);
      const usuario = credencial.user;

      await sendEmailVerification(usuario);

      await setDoc(doc(db, 'usuarios', usuario.uid), {
        email: usuario.email,
        criadoEm: new Date(),
      });

      Toast.show({
        type: 'success',
        text1: 'Cadastro realizado!',
        text2: `Um e-mail de confirmação foi enviado para ${usuario.email}.`,
        visibilityTime: 3500,
        onHide: () => navigation.replace('Login'),
      });

    } catch (erro: any) {
      let mensagem = 'Cadastro usuário.';
      if (erro.code === 'auth/email-already-in-use') {
        mensagem = 'Este e-mail já está cadastrado.';
      } else if (erro.code === 'auth/invalid-email') {
        mensagem = 'E-mail inválido.';
      } else if (erro.code === 'auth/weak-password') {
        mensagem = 'Senha muito fraca. Use pelo menos 6 caracteres.';
      }

      Toast.show({
        type: 'error',
        text1: 'Erro',
        text2: mensagem,
      });
    }
  }

  return (
    <KeyboardAvoidingView
      style={{ flex: 1, backgroundColor: '#18182a' }}
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <ScrollView
        contentContainerStyle={estilos.container}
        keyboardShouldPersistTaps="handled"
      >
        <NeumorphicField style={{ marginBottom: 18 }}>
          <TextInput
            placeholder="Email"
            value={email}
            onChangeText={setEmail}
            autoCapitalize="none"
            keyboardType="email-address"
            style={estilos.input}
            placeholderTextColor="#bbb"
          />
        </NeumorphicField>
        <NeumorphicField style={{ marginBottom: 18 }}>
          <TextInput
            placeholder="Senha"
            value={senha}
            onChangeText={setSenha}
            secureTextEntry
            style={estilos.input}
            placeholderTextColor="#bbb"
          />
        </NeumorphicField>
        <NeumorphicButton style={estilos.botao} onPress={registrarUsuario}>
          <Text style={estilos.textoBotao}>Cadastrar</Text>
        </NeumorphicButton>

        <View style={{ flexDirection: 'row', justifyContent: 'flex-end', marginTop: 18 }}>
          <NeumorphicButton style={estilos.botaoVoltar} onPress={() => navigation.replace('Login')}>
            <Text style={estilos.textoBotaoVoltar}>Voltar</Text>
          </NeumorphicButton>
        </View>

        <Toast />
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

const estilos = StyleSheet.create({
  container: {
    flexGrow: 1,
    justifyContent: 'center',
    padding: 20,
    backgroundColor: '#18182a',
  },
  input: {
    borderWidth: 0,
    borderRadius: 8,
    padding: 12,
    fontSize: 16,
    width: '100%',
    backgroundColor: 'transparent',
    color: '#fff',
  },
  botao: {
    marginTop: 10,
    width: '100%',
    borderRadius: 12,
    paddingVertical: 0,
    backgroundColor: 'transparent',
  },
  textoBotao: {
    color: '#fff',
    fontWeight: 'bold',
    fontSize: 18,
    letterSpacing: 1,
    textAlign: 'center',
    paddingVertical: 14,
  },
  botaoVoltar: {
    marginLeft: 8,
    width: 100,
    borderRadius: 12,
    backgroundColor: 'transparent',
  },
  textoBotaoVoltar: {
    color: '#fff',
    fontWeight: 'bold',
    fontSize: 16,
    textAlign: 'center',
    paddingVertical: 10,
  },
  neumorphicOuter: {
    shadowColor: '#000',
    shadowOffset: { width: 6, height: 6 },
    shadowOpacity: 0.5,
    shadowRadius: 8,
    elevation: 8,
    backgroundColor: '#18182a',
    borderRadius: 12,
    borderWidth: 1,
    borderColor: '#23243a',
    marginBottom: 0,
  },
  neumorphicInner: {
    shadowColor: '#fff',
    shadowOffset: { width: -4, height: -4 },
    shadowOpacity: 0.07,
    shadowRadius: 8,
    backgroundColor: '#18182a',
    borderRadius: 12,
    padding: 0,
  },
});