import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  StyleSheet,
  FlatList,
  TouchableOpacity,
  Alert,
  ScrollView,
  Linking,
  Dimensions,
  Animated,
} from 'react-native';
import { useRoute, useNavigation } from '@react-navigation/native';
import { doc, updateDoc, getFirestore } from 'firebase/firestore';
import { MaterialIcons } from '@expo/vector-icons';

const db = getFirestore();

const tonsMaiores = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const tonsMenores = ['Cm', 'C#m', 'Dm', 'D#m', 'Em', 'Fm', 'F#m', 'Gm', 'G#m', 'Am', 'A#m', 'Bm'];
const allTons = [...tonsMaiores, ...tonsMenores];

// Neumorphic container reutilizável
const NeumorphicContainer = ({ children, style }: any) => (
  <View style={[styles.neumorphicOuter, style]}>
    <View style={styles.neumorphicInner}>{children}</View>
  </View>
);

// Neumorphic button reutilizável
const NeumorphicButton = ({
  children,
  style,
  onPress,
  disabled,
  onPressIn,
  onPressOut,
  activeOpacity = 0.85,
  backgroundColor,
}: any) => {
  const anim = React.useRef(new Animated.Value(1)).current;
  return (
    <Animated.View style={[{ transform: [{ scale: anim }] }, style]}>
      <TouchableOpacity
        activeOpacity={activeOpacity}
        disabled={disabled}
        onPress={onPress}
        onPressIn={() => {
          anim.setValue(0.97);
          onPressIn && onPressIn();
        }}
        onPressOut={() => {
          Animated.spring(anim, {
            toValue: 1,
            useNativeDriver: true,
            friction: 3,
            tension: 40,
          }).start();
          onPressOut && onPressOut();
        }}
        style={[
          styles.neumorphicButtonOuter,
          backgroundColor ? { backgroundColor } : {},
          disabled && styles.disabledButton,
        ]}
      >
        <View style={[
          styles.neumorphicButtonInner,
          backgroundColor ? { backgroundColor } : {},
        ]}>
          {children}
        </View>
      </TouchableOpacity>
    </Animated.View>
  );
};

const DetalheRepertorio = () => {
  const route = useRoute();
  const navigation = useNavigation();
  const { repertorio } = route.params as any;

  const [titulo, setTitulo] = useState(repertorio.titulo || '');
  const [data, setData] = useState(repertorio.data || '');
  const [responsavel, setResponsavel] = useState(repertorio.responsavel || '');
  const [musicas, setMusicas] = useState(repertorio.musicas || []);
  const [editando, setEditando] = useState(false);
  const [salvando, setSalvando] = useState(false);

  // Campos para adicionar nova música
  const [novaNome, setNovaNome] = useState('');
  const [novaTom, setNovaTom] = useState('C');
  const [novaLinkLetra, setNovaLinkLetra] = useState('');
  const [novaLinkYoutube, setNovaLinkYoutube] = useState('');

  // Estado para o índice do tom de cada música ao editar
  const [tomIndexes, setTomIndexes] = useState(
    (repertorio.musicas || []).map((m: any) => {
      const idx = allTons.indexOf(m.tom);
      return idx >= 0 ? idx : 0;
    })
  );

  // Animação de alto relevo para o botão
  const saveAnim = React.useRef(new Animated.Value(1)).current;

  // Responsividade
  const screenWidth = Dimensions.get('window').width;
  const isSmallScreen = screenWidth < 400;

  // Atualizar campos das músicas existentes
  const handleChangeMusica = (idx: number, field: string, value: any) => {
    setMusicas(prev =>
      prev.map((m: any, i: number) =>
        i === idx ? { ...m, [field]: value } : m
      )
    );
    if (field === 'tom') {
      setTomIndexes(prev =>
        prev.map((v, i) => (i === idx ? allTons.indexOf(value) : v))
      );
    }
  };

  // Adicionar nova música
  const handleAdicionarMusica = () => {
    if (!novaNome.trim()) {
      Alert.alert('Atenção', 'Informe o nome da música.');
      return;
    }
    setMusicas(prev => [
      ...prev,
      {
        nome: novaNome,
        tom: novaTom,
        linkLetra: novaLinkLetra,
        linkYoutube: novaLinkYoutube,
      }
    ]);
    setTomIndexes(prev => [...prev, allTons.indexOf(novaTom)]);
    setNovaNome('');
    setNovaTom('C');
    setNovaLinkLetra('');
    setNovaLinkYoutube('');
  };

  const handleSalvar = async () => {
    setSalvando(true);
    try {
      await updateDoc(doc(db, 'repertorios', repertorio.id), {
        titulo,
        data,
        responsavel,
        musicas,
      });
      Alert.alert('Sucesso', 'Repertório atualizado!');
      setEditando(false);
    } catch (error) {
      Alert.alert('Erro', 'Não foi possível atualizar o repertório.');
    } finally {
      setSalvando(false);
    }
  };

  // Efeito de alto relevo no botão
  const handlePressIn = () => {
    Animated.spring(saveAnim, {
      toValue: 0.96,
      useNativeDriver: true,
    }).start();
  };
  const handlePressOut = () => {
    Animated.spring(saveAnim, {
      toValue: 1,
      friction: 3,
      tension: 40,
      useNativeDriver: true,
    }).start();
  };

  return (
    <View style={styles.bg}>
      <ScrollView
        contentContainerStyle={styles.container}
        keyboardShouldPersistTaps="handled"
        horizontal={false}
      >
        {/* HEADER NEUMÓRFICO */}
        <View style={styles.headerNeumorphic}>
          <View style={styles.headerRow}>
            <TouchableOpacity
              style={styles.headerIconBtn}
              onPress={() => navigation.navigate('Inicio')}
              activeOpacity={0.7}
            >
              <Text style={styles.homeEmoji}>🏠</Text>
            </TouchableOpacity>
            <Text style={styles.headerTitle}>🎵 Detalhes do Repertório</Text>
            <TouchableOpacity
              style={styles.headerIconBtn}
              onPress={() => navigation.goBack()}
              activeOpacity={0.7}
            >
              <View style={{ alignItems: 'center' }}>
                <MaterialIcons name="arrow-back" size={24} color="#a084e8" />
                <Text style={styles.backText}>BACK</Text>
              </View>
            </TouchableOpacity>
          </View>
        </View>
        {/* FIM HEADER */}

        <NeumorphicContainer style={styles.card}>
          <NeumorphicContainer style={styles.inputGroup}>
            <Text style={styles.label}>Título</Text>
            <TextInput
              style={[styles.input, !editando && styles.inputReadOnly]}
              value={titulo}
              editable={editando}
              onChangeText={setTitulo}
              placeholder="Título do repertório"
              placeholderTextColor="#90caf9"
            />
          </NeumorphicContainer>
          <NeumorphicContainer style={styles.inputGroup}>
            <Text style={styles.label}>Data</Text>
            <TextInput
              style={[styles.input, !editando && styles.inputReadOnly]}
              value={data}
              editable={editando}
              onChangeText={setData}
              placeholder="Data"
              placeholderTextColor="#90caf9"
            />
          </NeumorphicContainer>
          <NeumorphicContainer style={styles.inputGroup}>
            <Text style={styles.label}>Responsável</Text>
            <TextInput
              style={[styles.input, !editando && styles.inputReadOnly]}
              value={responsavel}
              editable={editando}
              onChangeText={setResponsavel}
              placeholder="Responsável"
              placeholderTextColor="#90caf9"
            />
          </NeumorphicContainer>
        </NeumorphicContainer>

        <Text style={styles.sectionTitle}>Músicas</Text>
        <NeumorphicContainer style={styles.musicListCard}>
          <FlatList
            data={musicas}
            keyExtractor={(_, idx) => idx.toString()}
            ListHeaderComponent={
              <View style={styles.musicHeader}>
                <View style={styles.editCell}><Text style={styles.editCellLabel}>YouTube</Text></View>
                <View style={styles.editCell}><Text style={styles.editCellLabel}>Tom</Text></View>
                <View style={styles.editCell}><Text style={styles.editCellLabel}>Letra</Text></View>
                <View style={styles.editCell}><Text style={styles.editCellLabel}>Música</Text></View>
              </View>
            }
            renderItem={({ item, index }) => (
              <View style={styles.musicItem}>
                {/* YouTube */}
                <View style={styles.editCell}>
                  <Text style={styles.editCellLabel}>YouTube</Text>
                  {editando ? (
                    <TextInput
                      style={[styles.editCellInput, { color: '#E53935', borderColor: '#E53935', textAlign: 'center', fontWeight: 'bold' }]}
                      value={item.linkYoutube}
                      onChangeText={text => handleChangeMusica(index, 'linkYoutube', text)}
                      placeholder="YouTube"
                      placeholderTextColor="#bbb"
                      autoCapitalize="none"
                      autoCorrect={false}
                      keyboardType="url"
                      numberOfLines={1}
                    />
                  ) : (
                    <TouchableOpacity
                      style={{ width: '100%' }}
                      onPress={() => item.linkYoutube ? Linking.openURL(item.linkYoutube) : null}
                      disabled={!item.linkYoutube}
                    >
                      <Text
                        style={[
                          styles.linkYoutube,
                          { textAlign: 'center', fontWeight: 'bold' },
                          !item.linkYoutube && { color: '#bbb', textDecorationLine: 'none' }
                        ]}
                        numberOfLines={1}
                        ellipsizeMode="tail"
                      >
                        {item.linkYoutube ? 'YouTube' : 'YouTube'}
                      </Text>
                    </TouchableOpacity>
                  )}
                </View>

                {/* Tom */}
                <View style={styles.editCell}>
                  <Text style={styles.editCellLabel}>Tom</Text>
                  {editando ? (
                    <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center' }}>
                      <TouchableOpacity
                        onPress={() => {
                          const newIdx = (tomIndexes[index] - 1 + allTons.length) % allTons.length;
                          handleChangeMusica(index, 'tom', allTons[newIdx]);
                        }}
                        style={{ padding: 4 }}
                      >
                        <Text style={{ color: '#ff9800', fontSize: 22 }}>{'<'}</Text>
                      </TouchableOpacity>
                      <View style={[styles.tomCircle, styles.tomCircleSelected, { marginHorizontal: 4 }]}>
                        <Text style={styles.tomCircleTextSelected}>
                          {allTons[tomIndexes[index]]}
                        </Text>
                      </View>
                      <TouchableOpacity
                        onPress={() => {
                          const newIdx = (tomIndexes[index] + 1) % allTons.length;
                          handleChangeMusica(index, 'tom', allTons[newIdx]);
                        }}
                        style={{ padding: 4 }}
                      >
                        <Text style={{ color: '#ff9800', fontSize: 22 }}>{'>'}</Text>
                      </TouchableOpacity>
                    </View>
                  ) : (
                    <View style={styles.tomCircleStatic}>
                      <Text style={styles.tomCircleTextSelected}>{item.tom}</Text>
                    </View>
                  )}
                </View>

                {/* Letra */}
                <View style={styles.editCell}>
                  <Text style={styles.editCellLabel}>Letra</Text>
                  {editando ? (
                    <TextInput
                      style={[styles.editCellInput, { color: '#ff9800', borderColor: '#ff9800', textAlign: 'center', fontWeight: 'bold' }]}
                      value={item.linkLetra}
                      onChangeText={text => handleChangeMusica(index, 'linkLetra', text)}
                      placeholder="Letra"
                      placeholderTextColor="#bbb"
                      autoCapitalize="none"
                      autoCorrect={false}
                      keyboardType="url"
                      numberOfLines={1}
                    />
                  ) : (
                    <TouchableOpacity
                      style={{ width: '100%' }}
                      onPress={() => item.linkLetra ? Linking.openURL(item.linkLetra) : null}
                      disabled={!item.linkLetra}
                    >
                      <Text
                        style={[
                          styles.linkLetra,
                          { textAlign: 'center', fontWeight: 'bold' },
                          !item.linkLetra && { color: '#bbb', textDecorationLine: 'none' }
                        ]}
                        numberOfLines={1}
                        ellipsizeMode="tail"
                      >
                        {item.linkLetra ? 'Letra' : 'Letra'}
                      </Text>
                    </TouchableOpacity>
                  )}
                </View>

                {/* Música */}
                <View style={styles.editCell}>
                  <Text style={styles.editCellLabel}>Música</Text>
                  {editando ? (
                    <TextInput
                      style={[styles.editCellInput, { textAlign: 'center', fontWeight: 'bold' }]}
                      value={item.nome}
                      onChangeText={text => handleChangeMusica(index, 'nome', text)}
                      placeholder="Música"
                      placeholderTextColor="#bbb"
                      numberOfLines={1}
                    />
                  ) : (
                    <Text style={[styles.musicText, { textAlign: 'center', fontWeight: 'bold' }]} numberOfLines={2}>{item.nome}</Text>
                  )}
                </View>
              </View>
            )}
            scrollEnabled={false}
          />
        </NeumorphicContainer>

        {editando && (
          <NeumorphicContainer style={[styles.inputGroup, styles.addMusicGroup]}>
            <Text style={styles.label}>Adicionar nova música</Text>
            <TextInput
              style={styles.input}
              placeholder="Nome da música"
              value={novaNome}
              onChangeText={setNovaNome}
            />
            <ScrollView
              horizontal
              showsHorizontalScrollIndicator={false}
              contentContainerStyle={styles.tonesScroll}
              style={{ width: '100%' }}
            >
              <Text style={{ alignSelf: 'center', marginRight: 8, color: '#ff9800', fontWeight: 'bold' }}>Tom:</Text>
              {tonsMaiores.concat(tonsMenores).map(item => (
                <TouchableOpacity
                  key={item}
                  style={[
                    styles.tomCircle,
                    novaTom === item && styles.tomCircleSelected,
                    isSmallScreen && { width: 32, height: 32 }
                  ]}
                  onPress={() => setNovaTom(item)}
                >
                  <Text style={[
                    styles.tomCircleText,
                    novaTom === item && styles.tomCircleTextSelected
                  ]}>{item}</Text>
                </TouchableOpacity>
              ))}
            </ScrollView>
            <TextInput
              style={styles.input}
              placeholder="Link da letra (ex: https://...)"
              value={novaLinkLetra}
              onChangeText={setNovaLinkLetra}
              autoCapitalize="none"
              autoCorrect={false}
              keyboardType="url"
            />
            <TextInput
              style={styles.input}
              placeholder="Link do YouTube (opcional)"
              value={novaLinkYoutube}
              onChangeText={setNovaLinkYoutube}
              autoCapitalize="none"
              autoCorrect={false}
              keyboardType="url"
            />
            <NeumorphicButton
              style={{ marginTop: 8, width: '100%' }}
              onPress={handleAdicionarMusica}
              backgroundColor="#43e97b"
            >
              <Text style={styles.addButtonText}>Adicionar Música</Text>
            </NeumorphicButton>
          </NeumorphicContainer>
        )}

        <View style={styles.buttonRow}>
          {editando ? (
            <NeumorphicButton
              style={{ flex: 1, marginRight: 8 }}
              onPress={handleSalvar}
              disabled={salvando}
              onPressIn={handlePressIn}
              onPressOut={handlePressOut}
              backgroundColor="#ff9800"
            >
              <Text style={[styles.actionButtonText, { color: '#23243a' }]}>
                {salvando ? "Salvando..." : "Salvar"}
              </Text>
            </NeumorphicButton>
          ) : (
            <NeumorphicButton
              style={{ flex: 1, marginRight: 8 }}
              onPress={() => setEditando(true)}
              backgroundColor="#a084e8"
            >
              <Text style={[styles.actionButtonText, { color: '#23243a' }]}>Editar</Text>
            </NeumorphicButton>
          )}
          <NeumorphicButton
            style={{ flex: 1, marginLeft: 8 }}
            onPress={() => navigation.goBack()}
            backgroundColor="#b3e5fc"
          >
            <Text style={[styles.actionButtonText, { color: '#23243a' }]}>Voltar</Text>
          </NeumorphicButton>
        </View>
      </ScrollView>
    </View>
  );
};

